import*as T from'three';import{V,path,cubic,Arc}from'../earth/curves.js';import{MaterialCurve,resultFor,MaterialBight,endRoute}from'./late-source.js';import{axialStep}from'./loose-rear-wire.js';
const U=V([0,0,1]),D=V([0,0,-1]),X=V([-1,0,0]);
export function makeGroundedHead(reference){const a=V(reference.data.points[0]),lead=a.clone().addScaledVector(D,.7),r=2.5,first=new Arc(lead.clone().addScaledVector(X,r),X.clone().negate(),D,r,Math.PI/2),p=first.getPoint(1),q=p.clone().addScaledVector(X,1),last=new Arc(q.clone().addScaledVector(D,-r),D,X,r,Math.PI/2),R=last.getPoint(1),A=V([-148,R.y,R.z+6]),B=V([-148,177,R.z+12]),C=V([-148,177,45]),E=V([-148,180.7593,51]),S=reference.head.getPoint(1),Ts=reference.head.getTangent(1);return path([new T.LineCurve3(a,lead),first,new T.LineCurve3(p,q),last,axialStep(R,A,U),axialStep(A,B,U),new T.LineCurve3(B,C),axialStep(C,E,U),cubic(E,E.clone().addScaledVector(U,8),S.clone().addScaledVector(Ts,-8),S)]);}
export function solveBoundaryWire(args,{stockMM=365}={}){const r=args.reference;if(args.ports[0].distanceTo(V(r.data.points[0]))>1e-7)throw Error('Boundary requires actual grounded FE4 port');const head=makeGroundedHead(r),free=endRoute(r,args.ports[1],args.tangents[1],args.value5),candidate=k=>path([head,new MaterialBight(r.coilBase,k),free]),minimum=candidate(0).getLength();if(minimum>stockMM)throw Error('Boundary minimum '+minimum+' exceeds chosen stock '+stockMM);let lo=0,hi=1.4;if(candidate(hi).getLength()<stockMM)throw Error('Boundary storage capacity');for(let i=0;i<42;i++){const m=(lo+hi)/2;if(candidate(m).getLength()<stockMM)lo=m;else hi=m;}const k=(lo+hi)/2,p=candidate(k),data={...r.data,targetMM:stockMM,materialStationsMM:r.data.materialStationsMM.map(s=>s*stockMM/r.data.targetMM)},curve=new MaterialCurve(p,data),report={phase:'FE48_COMPLETE_LCD_HELD_BEFORE_GATHER: separate grounded boundary candidate',value5:args.value5,targetMM:stockMM,lengthMM:p.getLength(),errorMM:p.getLength()-stockMM,minimumRouteMM:minimum,storageKind:'native-grounded head + retained case route with recomputed constant-stock bight',storageAngle:k,headMM:head.getLength(),oldGeneratedHeadMM:r.head.getLength(),continuousEarlyFeedNotClaimed:true};return resultFor(r,curve,report);}
